import{_ as a,o as l,c as e,a2 as r}from"./chunks/framework.E8pQZ6KS.js";const _=JSON.parse('{"title":"密码学","description":"","frontmatter":{},"headers":[],"relativePath":"安全方向/密码学.md","filePath":"安全方向/密码学.md","lastUpdated":1792430298000}'),i={name:"安全方向/密码学.md"};function d(o,t,h,n,s,u){return l(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="密码学" tabindex="-1">密码学 <a class="header-anchor" href="#密码学" aria-label="Permalink to &quot;密码学&quot;">​</a></h1><blockquote><p>安全的数学基石。校内对应「现代密码学」（第 3 学期，核心课）与「信息安全数学基础」（第 3 学期），是 FAFU 网安专业最鲜明的主线之一。</p></blockquote><h2 id="为什么学" tabindex="-1">为什么学 <a class="header-anchor" href="#为什么学" aria-label="Permalink to &quot;为什么学&quot;">​</a></h2><ul><li>加密、签名、哈希是所有安全机制（TLS、VPN、区块链、数据保护）的底层；</li><li>CTF Crypto 方向、协议分析、数字取证都离不开密码学思维；</li><li>密码学是「可证明安全」的学科，训练严谨的数学化思考方式。</li></ul><h2 id="前置知识" tabindex="-1">前置知识 <a class="header-anchor" href="#前置知识" aria-label="Permalink to &quot;前置知识&quot;">​</a></h2><ul><li><a href="./../专业基础/数学基础.html">数学基础</a>：同余、群环域、快速幂、扩展欧几里得</li></ul><h2 id="核心内容" tabindex="-1">核心内容 <a class="header-anchor" href="#核心内容" aria-label="Permalink to &quot;核心内容&quot;">​</a></h2><ul><li>古典密码与代换/置换</li><li>对称密码：DES / AES、分组模式（CBC、CTR）、流密码</li><li>非对称密码：RSA、Diffie-Hellman、ECC 原理</li><li>哈希函数与消息认证（MD5/SHA 系列、HMAC）</li><li>数字签名与公钥基础设施（PKI/Certificate）</li><li>攻击思路：暴力、频率分析、数学攻击（分解、离散对数）、侧信道概念</li></ul><h2 id="推荐资源" tabindex="-1">推荐资源 <a class="header-anchor" href="#推荐资源" aria-label="Permalink to &quot;推荐资源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资源</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>《图解密码技术》（结城浩）</td><td>书</td><td>零基础友好，图解清晰，入门首选</td></tr><tr><td>《深入浅出密码学》（Christof Paar 等）</td><td>书</td><td>理论与实践兼顾，配套实验</td></tr><tr><td>《密码编码学与网络安全》（Stallings）</td><td>教材</td><td>经典教材，体系完整（偏学术）</td></tr><tr><td>Dan Boneh: Cryptography I（Stanford/Coursera）</td><td>公开课</td><td>世界顶级密码学课程</td></tr></tbody></table><h2 id="学习建议" tabindex="-1">学习建议 <a class="header-anchor" href="#学习建议" aria-label="Permalink to &quot;学习建议&quot;">​</a></h2><ul><li><strong>数学优先</strong>：先吃透 [信息安全数学基础]，再学公钥密码会轻松很多；</li><li>每学一种算法，写代码实现一遍（RSA 加解密、AES 调用），并尝试用脚本「攻破」玩具版算法；</li><li>CTF Crypto 入门：从古典密码 + 简单数论题开始，逐步接触 RSA 常见攻击（低指数、共模、Wiener 等）——这些题目是对课堂知识的极好强化。</li></ul><h2 id="校内对应" tabindex="-1">校内对应 <a class="header-anchor" href="#校内对应" aria-label="Permalink to &quot;校内对应&quot;">​</a></h2><ul><li>现代密码学（第 3 学期，核心课）</li><li>信息安全数学基础（第 3 学期，核心课）</li></ul>',14)])])}const b=a(i,[["render",d]]);export{_ as __pageData,b as default};
